// spec: frogs-stonks
// Лягушки (банк, появление, вид и количество лута) и Stonks у Freebie.
// Код по спеке oracle/specs/frogs-stonks.md (правила 0–15). Данные — data/systems/frogs.json, их передаёт вызывающий:
// ядро само в файлы не ходит. Входы не меняются.

function tableRows(t) {
  return t.rows.map((r) => Object.fromEntries(t.columns.map((c, i) => [c, r[i]])));
}

/** @param {object} data содержимое data/systems/frogs.json */
export function makeFrogs(data) {
  const C = data.constants;
  const kinds = tableRows(data.tables.frogKinds);
  const totalWeight = kinds.reduce((s, k) => s + k.weight, 0);

  // правило 0: 63-битное целое из двух слов (первое — младшие 32 бита), старший бит обнулён
  function roll(g) {
    const lo = BigInt(g.u32());
    const hi = BigInt(g.u32()) & 0x7fffffffn;
    return (hi << 32n) | lo;
  }

  /** «a из n» (a может быть дробным): (U mod n + 1) − a ≤ eps */
  function chance(a, n, g) {
    const m = Number(roll(g) % BigInt(n));
    return (m + 1) - a <= C['compare.eps'];
  }

  /** «U mod n < a» */
  function below(n, a, g) {
    return Number(roll(g) % BigInt(n)) < a;
  }

  /** Правила 1–2. */
  function bankAdd(bank, n, g70, g71, cells) {
    let b = bank;
    for (let i = 0; i < n; i++) {
      const t = chance(C['triple.scale'] * cells.triple, C['triple.die'], g70);
      const x = chance(C['tenX.scale'] * cells.tenX, C['tenX.die'], g71);
      b = b + (t ? C['triple.factor'] : 1) * (x ? C['tenX.factor'] : 1);
    }
    return b;
  }

  /** Правило 4. */
  function spawnStep(s, dt) {
    let counter = s.counter + C['spawn.rate'] * dt;
    let bank = s.bank;
    let onScreen = s.onScreen;
    let spawned = false;
    if (counter - C['spawn.threshold'] >= -C['compare.eps']) {
      counter = counter - C['spawn.threshold'];
      if (bank > C['compare.eps']) {
        onScreen = onScreen + 1;
        bank = bank - C['spawn.cost'];
        spawned = true;
      }
    }
    return { counter, bank, onScreen, spawned };
  }

  /** Правила 5–10. */
  function createFrog(gens, cells, builtin) {
    const words = [];
    for (let i = 0; i < C['loot.words']; i++) words.push(gens.g55.u32());
    // правило 6
    const rem = words[C['kind.word']] % totalWeight;
    let acc = 0;
    let row = kinds[kinds.length - 1];
    for (const k of kinds) {
      acc += k.weight;
      if (rem < acc) { row = k; break; }
    }
    // правило 7
    const base = row.lo + (words[C['base.word']] % (row.hi - row.lo + 1));
    // правило 8
    const golden = chance(C['flag.scale'] * cells.golden, C['flag.die'], gens.g68);
    const big = chance(C['flag.scale'] * cells.big, C['flag.die'], gens.g69);
    const massive = big && chance(C['flag.scale'] * cells.massive, C['flag.die'], gens.g69);
    // правило 9
    let v = base * cells.lootMulti;
    if (golden) v = v * cells.goldenMulti;
    if (big) v = v * cells.bigMulti;
    if (massive) v = v * cells.massiveMulti;
    const u = builtin.irandom(C['round.die']);
    const fl = Math.floor(v);
    let amount = fl + ((u + 1) / C['round.scale'] <= v - fl ? 1 : 0);
    // правило 10: вне спеки
    if (row.gemBonus === 1 && cells.gemBonusMulti !== 1) amount = null;
    return { kind: row.kind, base, golden, big, massive, amount };
  }

  /** Правила 12–15. */
  function stonks(g, cells) {
    const crit = below(C['stonks.critDie'], C['stonks.critScale'] * cells.critChance, g);
    let ultra = false;
    if (crit) {
      roll(g);
      if (cells.ultraChance >= 100) ultra = true;
      else if (cells.ultraChance > 0) throw new Error('frogs: ультра-крит при 0 < шанс < 100 вне спеки');
    }
    const procs = [cells.chance, cells.chance, cells.chance].map((c) => below(C['stonks.procDie'], C['stonks.procScale'] * c, g));
    const f = cells.multi * (crit ? cells.critMulti : 1) * (ultra ? cells.ultraMulti : 1);
    const unit = [C['stonks.gems'], C['stonks.chests'], C['stonks.relics']];
    const gains = unit.map((b, i) => {
      if (!procs[i]) return 0;
      const x = b * f;
      if (!Number.isInteger(x)) throw new Error('frogs: дробная прибавка Stonks вне спеки');
      return x;
    });
    return { crit, ultra, procs, gains };
  }

  return { chance, below, bankAdd, spawnStep, createFrog, stonks };
}
EOF
